import{_ as r,c as l,o as e,ag as t}from"./chunks/framework.Bkod66qp.js";const b=JSON.parse('{"title":"예산관리규정","description":"","frontmatter":{"title":"예산관리규정","subtitle":"","doc_id":"","last_update":"2019-12-30","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/502_예산관리규정(191230).md","filePath":"regulation/502_예산관리규정(191230).md"}'),i={name:"regulation/502_예산관리규정(191230).md"};function o(n,a,s,d,c,h){return e(),l("div",null,a[0]||(a[0]=[t(`<h1 id="law-title" class="center" tabindex="-1">예산관리규정 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;예산관리규정 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2004.   3.  12
개정 2006.   2.  21
개정 2009.   3.   9
전부개정 2010.   9.   1
개정 2011.   2.   1
개정 2013.   3.  27
개정 2015.   9.  21
개정 2018.  12.  26
개정 2018.  12.  28
개정 2019.  12.  30</pre></div><h2 id="제1장-총-칙" tabindex="-1">제1장 총 칙 <a class="header-anchor" href="#제1장-총-칙" aria-label="Permalink to &quot;제1장 총 칙&quot;">​</a></h2><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 규정은 재단법인 서울문화재단(이하 “재단”이라 한다.)의 예산관리 업무를 효율적으로 수행하기 위하여 예산관리에 필요한 사항을 정함을 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (적용범위) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (적용범위) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(적용범위)</strong> 재단의 예산관리는 법령과 정관 또는 다른 규정에서 별도로 정하는 경우를 제외하고는 이 규정에서 정하는 바에 따른다.</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (예산기간) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (예산기간) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(예산기간)</strong> 예산기간은 정관에서 정한 회계연도를 기준으로 하며 예산통제 및 관리를 위하여 분기 또는 월별로 구분한다. 단, 중장기 계획을 요구하는 경우에는 그 계획기간을 예산기간으로 한다.</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (예산관리 조직 및 관리자) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (예산관리 조직 및 관리자) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(예산관리 조직 및 관리자)</strong> ① 예산의 관리는 예산주관부서에서 총괄하여 관리하며 각 부서에서는 사업부문별로 부문예산을 관리한다.<br> ② 대표이사는 경영본부장을 종합예산관리자로, 각 부서장을 부문예산관리자로, 예산주관부서장을 예산집행관리자로, 예산추산자를 예산담당자로 지명하여 예산의 편성, 조정, 집행을 관리토록 한다. &lt;개정 2011. 2. 1., 2018. 12. 28.&gt;<br> ③ 종합예산관리자의 직무는 다음 각호와 같다.</p><ol><li>예산편성지침의 입안 및 심의회부</li><li>각 부문예산의 종합 및 조정</li><li>종합예산(안)의 편성 및 심의회부</li><li>부문 및 종합예산의 집행실적분석, 평가 및 보고</li><li>예산의 변경, 이월, 전입, 재조정 및 초과집행 통제<br> ④ 부문예산관리자의 직무는 다음 각호와 같다.</li><li>예산편성지침에 의한 부문예산(안)의 편성</li><li>부문예산(안)에 대한 예산주관부서와의 협의 및 조정</li><li>확정 통보된 부문예산의 효율적인 집행</li><li>필요한 경우 확정된 부문예산의 변경신청</li><li>소관 부문예산의 집행실적 분석, 평가, 보고<br> ⑤ 예산집행관리자의 직무는 다음 각호와 같다.</li><li>예산의 편성 및 조정관리</li><li>예산의 변경 및 집행관리의 총괄</li><li>부문 및 종합예산의 집행실적 분석 및 평가<br> ⑥ 예산담당자의 직무는 다음 각 호와 같다.</li><li>예산의 편성 실무</li><li>예산집행관리부의 집행액 및 잔액의 관리</li><li>예산의 초과 또는 예산과목이 상이한 경우 집행거부</li><li>부문 및 종합예산의 집행실적 분석</li></ol><h2 id="article5" class="sr-only" tabindex="-1">제5조 (위임규정) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (위임규정) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(위임규정)</strong> 이 규정의 시행에 필요한 세부사항은 대표이사가 별도로 정하는 바에 의한다.</p><h2 id="제2장-예산편성" tabindex="-1">제2장 예산편성 <a class="header-anchor" href="#제2장-예산편성" aria-label="Permalink to &quot;제2장 예산편성&quot;">​</a></h2><h2 id="article6" class="sr-only" tabindex="-1">제6조 (예산의 내용) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (예산의 내용) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(예산의 내용)</strong> ① 예산은 예산총칙과 수지예산으로 구성한다.<br> ② 지출예산은 분야, 부문, 정책사업, 단위사업, 세부사업, 편성목으로 구분한다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (예산편성) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (예산편성) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(예산편성)</strong> ① 예산은 사업목표를 포함한 부문별 사업계획에 부합하여 편성하여야 한다.<br> ② 예산은 회계연도 개시 1개월 전까지 편성하여 이사회 의결을 거쳐 시장에게 제출하여야 한다.<br> ③ 예산승인 요청 시에는 사업계획서 및 예산내역서를 첨부한다.<br> ④ 부득이한 사유로 인하여 제1항에 의한 회계연도 개시일까지 예산을 편성하지 못할 때에는 다음 경비에 한하여 전년도 예산에 준하여 가예산을 편성 집행할 수 있다.</p><ol><li>임직원의 급여 및 경상관리비</li><li>공공요금 및 법정요금 등 집행이 불가피한 관리운영비</li><li>사업계획이 확정되어 계속 추진 중에 있는 사업비중 대표이사가 인정하는 경우<br> ⑤ 제4항에 의하여 집행된 예산은 당해연도 예산이 성립되면 그 성립된 예산에 의하여 집행된 것으로 본다.</li></ol><h2 id="article8" class="sr-only" tabindex="-1">제8조 (계속비) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (계속비) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(계속비)</strong> ① 완성에 수년을 요하는 사업은 비용의 총액과 연부액을 정하여 미리 이사회의 의결을 얻어 수년도에 걸쳐서 지출할 수 있다.<br> ② 제1항에 의하여 지출할 수 있는 연한은 당해 회계연도부터 5년 이내로 한다.</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (예비비) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (예비비) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(예비비)</strong> ① 예산 이외에 예측할 수 없는 지출 또는 예산초과 지출에 충당하기 위하여 예산에 예비비를 계상할 수 있다.<br> ② 예비비는 독립된 정책사업으로 계상하며 예비비를 사용하고자 할 때에는 사용 이유 및 금액을 명시한 조서를 작성하여 이사회의 의결을 거쳐 집행한다. 다만, 긴급을 요하는 사항은 우선 집행 후 사후 의결로 할 수 있다.</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (사업시행계획) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (사업시행계획) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(사업시행계획)</strong> 예산담당자는 제7조 제2항의 승인을 받은 예산에 근거하여 1개월 이내에 사업별, 분기별 예산집행계획서를 작성하여 보고해야 한다.</p><h2 id="article11" class="sr-only" tabindex="-1">제11조 (추가경정예산) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (추가경정예산) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(추가경정예산)</strong> ① 예산 성립 후 발생한 예산의 추가경정의 필요가 있을 때에는 추가경정예산을 편성할 수 있다.<br> ② 전항의 추가경정예산의 편성 및 승인의 절차는 본 예산에 준한다.<br> ③ 전항에도 불구하고 보조금, 출연금, 수탁사업, 기부금, 용역수입 등 수입이 확정되었으나, 시간상 이사회 소집이 어려울 경우에 한하여, 추가경정예산 성립 전 발생된 수입 및 지출 예산을 편성하여 집행할 수 있다. 단, 성립 전 수입 및 지출예산은 반드시 차기 이사회에 상정하여 승인을 얻어야 한다. &lt;개정 2013. 3. 27., 2019. 12. 26.&gt;</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (수입금마련 지출) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (수입금마련 지출) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(수입금마련 지출)</strong> ① 기편성된 예산과 이의 변경으로 충당할 수 없는 사업으로서 총수입이 총지출을 초과할 것으로 예상되는 사업에 대하여 대표이사가 승인하는 경우에는 예산과는 별도로 수입금마련을 위한 지출을 할 수 있다.<br> ② 이 경우 예산주관부서는 별도의 관리장부를 비치하여 관리한다.</p><h2 id="제3장-예산집행관리" tabindex="-1">제3장 예산집행관리 <a class="header-anchor" href="#제3장-예산집행관리" aria-label="Permalink to &quot;제3장 예산집행관리&quot;">​</a></h2><h2 id="article13" class="sr-only" tabindex="-1">제13조 (예산통제) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (예산통제) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(예산통제)</strong> ① 예산집행관리자는 예산의 집행을 통제하여 예산의 효율적인 운영을 도모한다.<br> ② 예산통제는 금액통제를 원칙으로 한다. 다만, 필요에 따라 수량통제, 단가통제를 병행할 수 있다.<br> ③ 모든 집행은 사전에 예산주관부서의 통제를 받아야하며 예산액 및 사용액을 기록하여야 한다.</p><h2 id="article14" class="sr-only" tabindex="-1">제14조 (예산집행관리부) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (예산집행관리부) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(예산집행관리부)</strong> 예산담당자와 사업담당자는 예산집행관리부를 각각 비치하여 관리해야 하며 항목별로 예산액 및 사용액을 기록하여 예산집행에 만전을 기한다.</p><h2 id="article15" class="sr-only" tabindex="-1">제15조 (예산의 이월) <a class="header-anchor" href="#article15" aria-label="Permalink to &quot;제15조 (예산의 이월) {#article15 .sr-only}&quot;">​</a></h2><p><strong>제15조(예산의 이월)</strong> 예산은 다음 연도에 이월하여 사용할 수 없다. 다만, 각 호의 경우는 다음 연도로 이월하여 사용할 수 있다. &lt;개정 2015. 9. 21.&gt;</p><ol><li>지출원인행위를 하고 불가피한 사유로 인하여 그 연도 내에 지출하지 못한 경비와 지출원인행위를 하지 아니한 그 부대경비로 대표이사 결재를 받은 경우</li><li>경비의 성질상 당해 연도 내에 그 지출을 끝내지 못할 것이 예상되어 그 취지를 세입세출예산에 명시하여 이사회의 의결을 받은 경우</li></ol><h2 id="article16" class="sr-only" tabindex="-1">제16조 (예산의 전용) <a class="header-anchor" href="#article16" aria-label="Permalink to &quot;제16조 (예산의 전용) {#article16 .sr-only}&quot;">​</a></h2><p><strong>제16조(예산의 전용)</strong> ① 예산집행상 불가피한 사유로 인하여 분야, 부문, 정책사업 간의 예산을 이용하고자 할 때에는 이사회의 승인을 받아야 한다. &lt;개정 2018. 12. 26.&gt;<br> ② 단위사업 이하의 예산을 전용하고자 할 경우에는 대표이사의 승인을 받아야 한다. 단, 차기 이사회에 보고해야 한다. &lt;개정 2018. 12. 26.&gt;<br> ③ 동일 세부사업 내 편성목 이하의 예산을 변경하고자 할 경우에는 정관상 직제의 부서장 책임 하에 결정하여 변경사용할 수 있다. &lt;개정 2018. 12. 26.&gt;</p><h2 id="article17" class="sr-only" tabindex="-1">제17조 (예산집행 실적 분석 및 보고) <a class="header-anchor" href="#article17" aria-label="Permalink to &quot;제17조 (예산집행 실적 분석 및 보고) {#article17 .sr-only}&quot;">​</a></h2><p><strong>제17조(예산집행 실적 분석 및 보고)</strong> 예산담당자는 분기별로 예산집행결과를 작성하여 예산집행관리자 및 종합예산관리자의 검토를 거쳐 대표이사에게 보고하여야 한다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 이 규정은 2004년 3월 12일부터 시행한다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2006. 2. 21.&gt;<br> 이 규정은 2006년 2월 21일부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2010. 9. 1.&gt;<br> 이 규정은 2013년 월 1일부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2013. 3. 27.&gt;<br> 이 규정은 2013년 3월 27일부터 시행한다.</p><h2 id="addendum5" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum5" aria-label="Permalink to &quot;부칙 {#addendum5 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2015. 9. 21.&gt;<br> 이 규정은 2015년 9월 21일부터 시행한다.</p><h2 id="addendum6" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum6" aria-label="Permalink to &quot;부칙 {#addendum6 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2018. 12. 26.&gt;<br> 이 규정은 이사회 승인을 득한 날로부터 시행한다.</p>`,54)]))}const g=r(i,[["render",o]]);export{b as __pageData,g as default};
